import React, { useState, useEffect } from 'react';

function VoiceControl() {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [commands, setCommands] = useState([
    { id: 1, command: 'Turn on the lights', executed: false },
    { id: 2, command: 'Play music', executed: false },
    { id: 3, command: 'Set temperature to 72 degrees', executed: false },
    { id: 4, command: 'Lock the front door', executed: false },
  ]);

  const startListening = () => {
    setIsListening(true);
    // Simulate voice recognition (in real app, this would use Web Speech API)
    setTimeout(() => {
      setIsListening(false);
      setTranscript('Turn on the living room lights');
    }, 3000);
  };

  const stopListening = () => {
    setIsListening(false);
  };

  const executeCommand = (commandId) => {
    setCommands(commands.map(cmd =>
      cmd.id === commandId ? { ...cmd, executed: true } : cmd
    ));

    // Simulate command execution
    setTimeout(() => {
      setCommands(commands.map(cmd =>
        cmd.id === commandId ? { ...cmd, executed: false } : cmd
      ));
    }, 2000);
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {/* Voice Control Interface */}
      <div className="bg-white rounded-lg shadow-md p-8 text-center">
        <h1 className="text-3xl font-bold text-secondary mb-6">
          Voice Control Center
        </h1>

        {/* Microphone Button */}
        <div className="mb-8">
          <button
            onClick={isListening ? stopListening : startListening}
            className={`w-32 h-32 rounded-full transition-all duration-300 ${
              isListening
                ? 'bg-red-500 hover:bg-red-600 animate-pulse'
                : 'bg-primary hover:bg-primary/90'
            } text-white font-medium text-lg shadow-lg hover:shadow-xl`}
          >
            {isListening ? 'Listening...' : '🎤 Speak'}
          </button>
        </div>

        {/* Transcript Display */}
        {transcript && (
          <div className="bg-light-bg rounded-lg p-4 mb-6">
            <p className="text-lg text-neutral font-medium">
              You said: <span className="text-primary">"{transcript}"</span>
            </p>
          </div>
        )}

        {/* Status Indicator */}
        <div className="flex items-center justify-center space-x-2 text-sm">
          <div className={`w-3 h-3 rounded-full ${isListening ? 'bg-red-500' : 'bg-green-500'}`}></div>
          <span className={isListening ? 'text-red-600' : 'text-green-600'}>
            {isListening ? 'Recording' : 'Ready'}
          </span>
        </div>
      </div>

      {/* Quick Commands */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-bold text-secondary mb-6">Quick Commands</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {commands.map((command) => (
            <button
              key={command.id}
              onClick={() => executeCommand(command.id)}
              disabled={command.executed}
              className={`p-4 rounded-lg border-2 transition-all ${
                command.executed
                  ? 'bg-green-100 border-green-500 text-green-700'
                  : 'border-primary text-primary hover:bg-primary hover:text-white'
              } font-medium`}
            >
              {command.executed ? '✓ ' : ''}{command.command}
            </button>
          ))}
        </div>
      </div>

      {/* Voice Settings */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-2xl font-bold text-secondary mb-6">Voice Settings</h2>
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <span className="text-neutral">Voice Feedback</span>
            <label className="relative inline-flex items-center cursor-pointer">
              <input type="checkbox" className="sr-only peer" defaultChecked />
              <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/25 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
            </label>
          </div>

          <div className="flex items-center justify-between">
            <span className="text-neutral">Auto-execute commands</span>
            <label className="relative inline-flex items-center cursor-pointer">
              <input type="checkbox" className="sr-only peer" />
              <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-primary/25 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-primary"></div>
            </label>
          </div>
        </div>
      </div>
    </div>
  );
}

export default VoiceControl;
